import json
from pathlib import Path
from unittest.mock import patch
from flagquantum import synth
from flagquantum.compiler.optimization import commutation
from flagquantum.core.ir import Instruction

predicate = commutation.commute
controlled = frozenset({'cx', 'cy', 'crx', 'cry'})
def historical(left: Instruction, right: Instruction) -> bool:
    if left.name in controlled and right.name in controlled and len(left.wires) == len(right.wires) == 2 and left.wires != right.wires and not set(left.wires).isdisjoint(right.wires):
        return False
    return predicate(left, right)
path=Path('tests/fixtures/classiq_qmod/quantum_thermal_state_preparation.qmod')
rows={}
for variant, checker in (('earlier decision boundary',historical),('current controlled commutation',predicate)):
    with patch.object(commutation,'commute',checker):
        program=synth.synthesize(path,max_qubits=11,max_workspace=1,max_operations=25000)
    resource=program.report['resources']
    rows[variant]={'n_operations':resource.n_operations,'depth':resource.depth,'counts':dict(resource.operation_counts),'channel_count':resource.channel_count,'workspace_qubits':program.report['workspace_qubits']}
report={'scope':'Untimed original thermal-reset compiler cost diagnosis; no performance or channel-semantic claim','source_head':'e6dc85d30830563456c7e5735a4490100ebb848e','rows':rows}
Path('/private/tmp/fq-controlled-thermal-cost-diagnosis-20261122.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report),flush=True)
